"""Stage 3: distill the XGBoost diabetes model into an FHE-friendly MLP.

Reference = XGBoost (ground truth for the FHE pipeline).
Surrogate = 1-hidden-layer MLP, sigmoid activations, standardized inputs.
Distillation = regression on the XGBoost logit (soft targets).

Outputs (model/surrogate/):
  mlp_surrogate_first_fit.json  this first fit's weights, scaler, threshold
                                (the shipped mlp_surrogate.json is finalize_surrogate.py's)
  distill_report.json     metrics: xgb vs labels, mlp vs labels, mlp vs xgb agreement
  preact_envelope.json    per-unit pre-activation envelopes over the FULL corpus (gate data)
"""
import json, sys, time
import numpy as np
import pandas as pd
import xgboost as xgb
from sklearn.neural_network import MLPRegressor
from sklearn.metrics import roc_auc_score, precision_recall_fscore_support

RNG = 42
REPO = sys.argv[1] if len(sys.argv) > 1 else "."
ART = f"{REPO}/model/surrogate"
THRESH_P = 0.64
THRESH_LOGIT = float(np.log(THRESH_P / (1 - THRESH_P)))

feature_cols = json.load(open(f"{REPO}/model/feature_cols.json"))
train = pd.read_parquet(f"{REPO}/data/cdc_diabetes_train.parquet")
test = pd.read_parquet(f"{REPO}/data/cdc_diabetes_test.parquet")
full = pd.read_parquet(f"{REPO}/data/cdc_diabetes_prepped.parquet")

Xtr = train[feature_cols].to_numpy(np.float32); ytr = train["Diabetes_binary"].to_numpy()
Xte = test[feature_cols].to_numpy(np.float32);  yte = test["Diabetes_binary"].to_numpy()
Xfull = full[feature_cols].to_numpy(np.float32)

model = xgb.XGBClassifier(); model.load_model(f"{REPO}/model/xgb_diabetes_model.json")
p_tr = model.predict_proba(Xtr)[:, 1]; p_te = model.predict_proba(Xte)[:, 1]
logit_tr = np.log(p_tr / (1 - p_tr)); logit_te = np.log(p_te / (1 - p_te))

# client_clear standardization (folded into published scaler)
mu = Xtr.mean(axis=0); sd = Xtr.std(axis=0)
Ztr = (Xtr - mu) / sd; Zte = (Xte - mu) / sd; Zfull = (Xfull - mu) / sd

H = int(sys.argv[2]) if len(sys.argv) > 2 else 16
t0 = time.time()
mlp = MLPRegressor(hidden_layer_sizes=(H,), activation="logistic", solver="adam",
                   alpha=1e-4, batch_size=512, learning_rate_init=1e-3,
                   max_iter=60, early_stopping=True, n_iter_no_change=8,
                   validation_fraction=0.1, random_state=RNG, verbose=False)
mlp.fit(Ztr, logit_tr)
fit_s = time.time() - t0

W1, W2 = mlp.coefs_; b1, b2 = mlp.intercepts_

def forward_logit(Z):
    pre = Z @ W1 + b1
    hid = 1.0 / (1.0 + np.exp(-pre))
    return (hid @ W2 + b2).ravel(), pre

def metrics(y, logit, name):
    p = 1 / (1 + np.exp(-logit))
    pred = (logit >= THRESH_LOGIT).astype(int)
    pr, rc, f1, _ = precision_recall_fscore_support(y, pred, average="binary", zero_division=0)
    return {"name": name, "roc_auc": float(roc_auc_score(y, p)),
            "precision": float(pr), "recall": float(rc), "f1": float(f1),
            "pos_rate": float(pred.mean())}

mlp_logit_te, _ = forward_logit(Zte)
mlp_logit_tr, _ = forward_logit(Ztr)

m_xgb = metrics(yte, logit_te, "xgb_reference_test")
m_mlp = metrics(yte, mlp_logit_te, "mlp_surrogate_test")
agree = float(((mlp_logit_te >= THRESH_LOGIT) == (logit_te >= THRESH_LOGIT)).mean())
logit_mae = float(np.abs(mlp_logit_te - logit_te).mean())

# ---- activation-range gate: pre-activation envelope over the FULL corpus ----
_, pre_full = forward_logit(Zfull)
qs = np.percentile(pre_full, [0, 0.01, 0.1, 50, 99.9, 99.99, 100], axis=0)
env = {"units": H,
       "per_unit_min": pre_full.min(axis=0).tolist(),
       "per_unit_max": pre_full.max(axis=0).tolist(),
       "per_unit_p001": qs[1].tolist(), "per_unit_p9999": qs[5].tolist(),
       "global_min": float(pre_full.min()), "global_max": float(pre_full.max()),
       "global_p001": float(np.percentile(pre_full, 0.01)),
       "global_p9999": float(np.percentile(pre_full, 99.99))}

# output-layer operand range (hidden in [0,1], so bounded by construction)
mlp_logit_full, _ = forward_logit(Zfull)
env["output_logit_min"] = float(mlp_logit_full.min())
env["output_logit_max"] = float(mlp_logit_full.max())

import os; os.makedirs(ART, exist_ok=True)
json.dump({"feature_cols": feature_cols, "mu": mu.tolist(), "sd": sd.tolist(),
           "W1": W1.tolist(), "b1": b1.tolist(), "W2": W2.ravel().tolist(),
           "b2": float(np.ravel(b2)[0]), "hidden": H,
           "threshold_logit": THRESH_LOGIT, "threshold_proba": THRESH_P},
          open(f"{ART}/mlp_surrogate_first_fit.json", "w"))
json.dump({"fit_seconds": fit_s, "xgb": m_xgb, "mlp": m_mlp,
           "decision_agreement_vs_xgb": agree, "logit_mae_vs_xgb": logit_mae,
           "train_auc_mlp": metrics(ytr, mlp_logit_tr, "train")["roc_auc"]},
          open(f"{ART}/distill_report.json", "w"), indent=1)
json.dump(env, open(f"{ART}/preact_envelope.json", "w"), indent=1)

print(json.dumps({"fit_s": round(fit_s, 1), "xgb": m_xgb, "mlp": m_mlp,
                  "agreement": agree, "logit_mae": logit_mae,
                  "preact_global": [env["global_min"], env["global_max"]],
                  "preact_p_band": [env["global_p001"], env["global_p9999"]]}, indent=1))
